import{_ as e,o as a,c as r,Q as t}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"Maltese for Beginners","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/index.md","filePath":"en/more/maltese/grammar/index.md"}'),n={name:"en/more/maltese/grammar/index.md"},s=t('<h1 id="maltese-for-beginners" tabindex="-1">Maltese for Beginners <a class="header-anchor" href="#maltese-for-beginners" aria-label="Permalink to &quot;Maltese for Beginners&quot;">​</a></h1><p>These notes are for beginner learners. Maltese is written with the standard Latin alphabet. English glosses are intended as quick references; meanings may vary with context and collocation.</p><h2 id="learning-materials" tabindex="-1">Learning Materials <a class="header-anchor" href="#learning-materials" aria-label="Permalink to &quot;Learning Materials&quot;">​</a></h2><ol><li><a href="./00-requirements.html">Editorial requirements</a>: the scope and original requirements for this learning resource.</li><li><a href="./01-vocabulary.html">Categorized basic vocabulary</a>: ten core categories, with at least 20 entries each. Family, home, animals, plants, transport, and time include relevant singular/plural forms; the animal table also notes male and female terms. Time is ordered from hours to days, weeks, months, and years. Question words and prepositions are ordered approximately by frequency.</li><li><a href="./02-phrases.html">200 useful phrases</a>: ten situations with 20 phrases each, covering greetings, politeness, conversation, food, shopping, travel, time, everyday needs, and emergencies.</li><li><a href="./03-person-conjugation.html">Personal pronouns and verb conjugation</a>: rules first, followed by five common verbs and five verbs each with initial and medial <code>għ</code>, fully conjugated for seven persons. Includes example sentences; tense is not covered.</li><li><a href="./04-verbs-tenses.html">Verbs and basic tenses</a>: imperfect, perfect, and future constructions, with verb tables for all seven persons and trilingual examples.</li><li><a href="./05-numbers.html">Numbers and numeral grammar</a>: cardinal numbers, compound numbers, 20 ordinal numbers, and ten large-number examples.</li><li><a href="./06-time-calendar.html">Telling the time</a>: o&#39;clock, parts of the day and relative dates, clock times, and durations. Includes the uses of <code>u</code>, <code>nofs</code>, and <code>neqsin</code>, plus 20 time-of-day and 20 duration examples.</li><li><a href="./07-dates.html">Dates, weekdays, months, and seasons</a>: date expressions, calendar vocabulary, relative week/month/year expressions, and 20 examples.</li><li><a href="./08-prepositions.html">Common prepositions</a>: 44 useful prepositions and collocations, comparison with five article forms, notes on contraction, and example sentences.</li></ol><h2 id="suggested-study-order" tabindex="-1">Suggested Study Order <a class="header-anchor" href="#suggested-study-order" aria-label="Permalink to &quot;Suggested Study Order&quot;">​</a></h2><p>Start with the alphabet and categorized vocabulary, then practise the 200 phrases by situation. Continue with pronouns and conjugation, tenses, numbers, time, dates, and prepositions. Choose five to ten words a day, substitute them into the example sentences, and read them aloud.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>ċ</code>, <code>ġ</code>, <code>ħ</code>, and <code>ż</code> are distinct Maltese letters. Preserve the spellings of <code>għ</code> and <code>ie</code> as well.</li><li>Regional and colloquial variation exists. These notes prioritize common standard written forms; some expressions have other natural alternatives.</li><li>Maltese verbs do not have an infinitive that corresponds exactly to English <code>to + verb</code>. The vocabulary list uses common citation forms; see the conjugation tables for person-specific forms.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://en.wikipedia.org/wiki/Maltese_language" target="_blank" rel="noreferrer">Maltese language (overview and grammar)</a></li><li><a href="https://kunsilltalmalti.gov.mt/" target="_blank" rel="noreferrer">National Council for the Maltese Language</a></li><li><a href="https://www.um.edu.mt/library/oar/handle/123456789/351" target="_blank" rel="noreferrer">University of Malta Library: Maltese languages and literatures</a></li></ul><p>These notes are an introductory reference. For formal writing or important translations, consult a Maltese dictionary or a native speaker.</p>',11),o=[s];function i(l,d,c,m,h,u){return a(),r("div",null,o)}const g=e(n,[["render",i]]);export{p as __pageData,g as default};
